KIT='/home/hatch/workspace/makefun-watch/kits/gta6-twitch-ccu-forecast-01/gta6-twitch-ccu-forecast-01-kit/input'
def parse(t): return datetime.fromisoformat(t.replace('Z','+00:00'))
d=json.load(open(f'{KIT}/p00.in'))
def series(comp):
    ds=parse(comp['day_start']); s={}
    for row in comp.get('hourly') or []:
        try:
            hr=(parse(row['from'])-ds).total_seconds()/3600; v=row['viewers']
        except Exception: continue
        if 0<=hr<24 and abs(hr-round(hr))<1e-9 and v and v>0:
            s[int(hr)+1]=float(v)
    return s
usable=[]
for comp in d['comparables']:
    s=series(comp)
    scored=sum(1 for h in range(2,25) if h in s)
    tier='?'
    u=comp.get('unlock','')
    for t in ['comparable','early-access-contaminated','weak','target-history']:
        if f'Tier: {t}' in u: tier=t
    print(f"{comp['name'][:45]:45s} tier={tier:28s} h1={s.get(1)} scored={scored} day={comp['day_start'][:10]}")
